export function isExhibitApproach(foot,facing,state,layer){if(facing!=='up'||state!=='OPEN'||layer!=='ground'||!Array.isArray(foot)||foot.length!==2||Reflect.ownKeys(foot).length!==3)return false;const d=[0,1].map(i=>Object.getOwnPropertyDescriptor(foot,String(i)));if(d.some(x=>!x||!x.enumerable||!Object.hasOwn(x,'value')||!Number.isInteger(x.value)))return false;const[x,y]=d.map(x=>x.value);return EXHIBIT_ROWS.some(([yy,a,b])=>y===yy&&x>=a&&x<b)}
